"""Curated advanced Python tasks with materially different algorithms."""

ADVANCED_TASK_CODE_SPECS = (
    ("binary_search", "Write a Python function that returns the first index of a target in an ascending sequence, or -1 when absent, using binary search without mutating the sequence.", "def first_binary_search(values, target):\n    left, right = 0, len(values)\n    while left < right:\n        middle = (left + right) // 2\n        if values[middle] < target:\n            left = middle + 1\n        else:\n            right = middle\n    return left if left < len(values) and values[left] == target else -1"),
    ("merge_intervals", "Write a Python function that merges overlapping closed intervals, returns sorted new lists, accepts intervals in any order, and does not mutate the input.", "def merge_closed_intervals(intervals):\n    ordered = sorted((start, end) for start, end in intervals)\n    merged = []\n    for start, end in ordered:\n        if not merged or start > merged[-1][1]:\n            merged.append([start, end])\n        else:\n            merged[-1][1] = max(merged[-1][1], end)\n    return merged"),
    ("interval_intersections", "Write a Python function that returns all intersections between two lists of disjoint closed intervals already sorted by start, using a two-pointer scan and without mutating either input.", "def intersect_interval_lists(first, second):\n    result = []\n    left = right = 0\n    while left < len(first) and right < len(second):\n        start = max(first[left][0], second[right][0])\n        end = min(first[left][1], second[right][1])\n        if start <= end:\n            result.append([start, end])\n        if first[left][1] < second[right][1]:\n            left += 1\n        else:\n            right += 1\n    return result"),
    ("maximum_nonoverlapping_intervals", "Write a Python function that selects the maximum number of mutually nonoverlapping half-open intervals, returns selected intervals ordered by finishing time, and does not mutate the input.", "def select_nonoverlapping(intervals):\n    selected = []\n    last_end = None\n    for start, end in sorted(intervals, key=lambda item: (item[1], item[0])):\n        if last_end is None or start >= last_end:\n            selected.append((start, end))\n            last_end = end\n    return selected"),
    ("breadth_first_distances", "Write a Python function that computes unweighted shortest-path distances from a start node in a graph represented by an adjacency dictionary, ignores unreachable nodes, and does not mutate the graph.", "def breadth_first_distances(graph, start):\n    distances = {start: 0}\n    queue = [start]\n    position = 0\n    while position < len(queue):\n        node = queue[position]\n        position += 1\n        for neighbor in graph.get(node, []):\n            if neighbor not in distances:\n                distances[neighbor] = distances[node] + 1\n                queue.append(neighbor)\n    return distances"),
    ("topological_sort", "Write a Python function that topologically orders every node in a directed adjacency dictionary, includes nodes appearing only as neighbors, and raises ValueError when a cycle exists.", "def topological_order(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    indegree = {node: 0 for node in nodes}\n    for neighbors in graph.values():\n        for neighbor in neighbors:\n            indegree[neighbor] += 1\n    ready = [node for node in nodes if indegree[node] == 0]\n    result = []\n    while ready:\n        node = ready.pop()\n        result.append(node)\n        for neighbor in graph.get(node, []):\n            indegree[neighbor] -= 1\n            if indegree[neighbor] == 0:\n                ready.append(neighbor)\n    if len(result) != len(nodes):\n        raise ValueError(\"graph contains a cycle\")\n    return result"),
    ("connected_components", "Write a Python function that returns the connected components of an undirected adjacency dictionary as sets, including neighbor-only nodes, without mutating the graph.", "def connected_components(graph):\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    remaining = set(nodes)\n    components = []\n    while remaining:\n        start = remaining.pop()\n        component = {start}\n        stack = [start]\n        while stack:\n            node = stack.pop()\n            for neighbor in graph.get(node, []):\n                if neighbor in remaining:\n                    remaining.remove(neighbor)\n                    component.add(neighbor)\n                    stack.append(neighbor)\n        components.append(component)\n    return components"),
    ("dijkstra_distances", "Write a Python function that computes shortest distances from a start node in a nonnegative weighted adjacency dictionary using a heap supplied through ordinary list operations, without mutating the graph.", "def shortest_weighted_distances(graph, start):\n    distances = {start: 0}\n    pending = [(0, start)]\n    while pending:\n        pending.sort(reverse=True)\n        distance, node = pending.pop()\n        if distance != distances.get(node):\n            continue\n        for neighbor, weight in graph.get(node, []):\n            candidate = distance + weight\n            if candidate < distances.get(neighbor, float(\"inf\")):\n                distances[neighbor] = candidate\n                pending.append((candidate, neighbor))\n    return distances"),
    ("balanced_delimiters", "Write a Python function that checks whether parentheses, brackets, and braces in a string are correctly nested while ignoring all other characters.", "def delimiters_are_balanced(text):\n    opening = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\n    stack = []\n    for character in text:\n        if character in opening.values():\n            stack.append(character)\n        elif character in opening:\n            if not stack or stack.pop() != opening[character]:\n                return False\n    return not stack"),
    ("run_length_encode", "Write a Python function that run-length encodes a string as a list of character-count tuples, returns an empty list for empty input, and preserves character case.", "def run_length_encode(text):\n    if not text:\n        return []\n    encoded = []\n    current = text[0]\n    count = 1\n    for character in text[1:]:\n        if character == current:\n            count += 1\n        else:\n            encoded.append((current, count))\n            current, count = character, 1\n    encoded.append((current, count))\n    return encoded"),
    ("longest_common_prefix", "Write a Python function that returns the longest common prefix of a sequence of strings, returns an empty string for empty input, and does not mutate the strings.", "def longest_common_prefix(values):\n    if not values:\n        return \"\"\n    prefix = values[0]\n    for value in values[1:]:\n        limit = min(len(prefix), len(value))\n        index = 0\n        while index < limit and prefix[index] == value[index]:\n            index += 1\n        prefix = prefix[:index]\n        if not prefix:\n            break\n    return prefix"),
    ("group_anagrams", "Write a Python function that groups strings that are anagrams, preserves first-group and within-group input order, treats case as significant, and does not mutate the input.", "def group_anagrams(values):\n    groups = {}\n    order = []\n    for value in values:\n        key = tuple(sorted(value))\n        if key not in groups:\n            groups[key] = []\n            order.append(key)\n        groups[key].append(value)\n    return [groups[key] for key in order]"),
    ("edit_distance", "Write a Python function that computes the Levenshtein edit distance between two strings using dynamic programming with one row of storage.", "def edit_distance(first, second):\n    previous = list(range(len(second) + 1))\n    for left_index, left_character in enumerate(first, 1):\n        current = [left_index]\n        for right_index, right_character in enumerate(second, 1):\n            current.append(min(current[-1] + 1, previous[right_index] + 1, previous[right_index - 1] + (left_character != right_character)))\n        previous = current\n    return previous[-1]"),
    ("spiral_matrix", "Write a Python function that returns elements of a rectangular matrix in clockwise spiral order, returns an empty list for an empty matrix, and does not mutate the matrix.", "def spiral_values(matrix):\n    if not matrix:\n        return []\n    top, bottom = 0, len(matrix) - 1\n    left, right = 0, len(matrix[0]) - 1\n    result = []\n    while top <= bottom and left <= right:\n        result.extend(matrix[top][left:right + 1])\n        top += 1\n        for row in range(top, bottom + 1):\n            result.append(matrix[row][right])\n        right -= 1\n        if top <= bottom:\n            result.extend(reversed(matrix[bottom][left:right + 1]))\n            bottom -= 1\n        if left <= right:\n            for row in range(bottom, top - 1, -1):\n                result.append(matrix[row][left])\n            left += 1\n    return result"),
    ("prefix_range_sums", "Write a Python function that answers inclusive range-sum queries over a numeric sequence using one prefix-sum table and does not mutate the inputs.", "def range_sum_queries(values, queries):\n    prefix = [0]\n    for value in values:\n        prefix.append(prefix[-1] + value)\n    result = []\n    for start, end in queries:\n        if start < 0 or end < start or end >= len(values):\n            raise ValueError(\"invalid range\")\n        result.append(prefix[end + 1] - prefix[start])\n    return result"),
    ("maximum_subarray", "Write a Python function that returns the maximum sum of a non-empty contiguous subarray using a linear scan and does not mutate the sequence.", "def maximum_subarray_sum(values):\n    if not values:\n        raise ValueError(\"values must be non-empty\")\n    best = current = values[0]\n    for value in values[1:]:\n        current = max(value, current + value)\n        best = max(best, current)\n    return best"),
    ("two_sum_indices", "Write a Python function that returns the first pair of indices encountered whose values sum to a target, returns None when no pair exists, and does not mutate the sequence.", "def first_two_sum_indices(values, target):\n    seen = {}\n    for index, value in enumerate(values):\n        complement = target - value\n        if complement in seen:\n            return seen[complement], index\n        seen.setdefault(value, index)\n    return None"),
    ("longest_unique_substring", "Write a Python function that returns the length of the longest substring containing no repeated characters using a sliding window.", "def longest_unique_substring_length(text):\n    last_seen = {}\n    start = 0\n    best = 0\n    for index, character in enumerate(text):\n        if character in last_seen and last_seen[character] >= start:\n            start = last_seen[character] + 1\n        last_seen[character] = index\n        best = max(best, index - start + 1)\n    return best"),
    ("histogram_largest_rectangle", "Write a Python function that returns the largest rectangular area under a nonnegative histogram using a monotonic stack and does not mutate the heights.", "def largest_histogram_rectangle(heights):\n    stack = []\n    best = 0\n    for index, height in enumerate(list(heights) + [0]):\n        start = index\n        while stack and stack[-1][1] > height:\n            position, previous = stack.pop()\n            best = max(best, previous * (index - position))\n            start = position\n        stack.append((start, height))\n    return best"),
    ("flatten_nested_mapping", "Write a Python function that flattens nested dictionaries into dot-separated key paths, treats non-dictionary values as leaves, and does not mutate the mapping.", "def flatten_mapping(mapping):\n    result = {}\n    stack = [(\"\", mapping)]\n    while stack:\n        prefix, value = stack.pop()\n        if isinstance(value, dict):\n            for key, child in value.items():\n                path = str(key) if not prefix else prefix + \".\" + str(key)\n                stack.append((path, child))\n        else:\n            result[prefix] = value\n    return result"),
    ("mapping_changes", "Write a Python function that compares two dictionaries and returns separate dictionaries for added, removed, and changed keys without mutating either input.", "def mapping_changes(before, after):\n    added = {key: after[key] for key in after.keys() - before.keys()}\n    removed = {key: before[key] for key in before.keys() - after.keys()}\n    changed = {key: (before[key], after[key]) for key in before.keys() & after.keys() if before[key] != after[key]}\n    return {\"added\": added, \"removed\": removed, \"changed\": changed}"),
    ("relational_inner_join", "Write a Python function that performs an inner join between two record lists on configurable key fields, merges matching records into new dictionaries, and preserves left-then-right match order.", "def inner_join_records(left_rows, right_rows, left_key, right_key):\n    index = {}\n    for row in right_rows:\n        index.setdefault(row[right_key], []).append(row)\n    result = []\n    for left in left_rows:\n        for right in index.get(left[left_key], []):\n            merged = left.copy()\n            merged.update(right)\n            result.append(merged)\n    return result"),
    ("dependency_closure", "Write a Python function that returns every transitive dependency reachable from a requested item in a dependency dictionary, excludes the item itself, and handles cycles.", "def transitive_dependencies(graph, item):\n    found = set()\n    stack = list(graph.get(item, []))\n    while stack:\n        dependency = stack.pop()\n        if dependency == item or dependency in found:\n            continue\n        found.add(dependency)\n        stack.extend(graph.get(dependency, []))\n    return found"),
    ("top_k_frequencies", "Write a Python function that returns the k most frequent hashable values ordered by descending frequency and then first occurrence, without mutating the input.", "def top_k_frequent(values, k):\n    counts = {}\n    first = {}\n    for index, value in enumerate(values):\n        counts[value] = counts.get(value, 0) + 1\n        first.setdefault(value, index)\n    ordered = sorted(counts, key=lambda value: (-counts[value], first[value]))\n    return ordered[:max(0, k)]"),
)
